with cohort as (select split_part(v,'/',1)::date race_date,split_part(v,'/',2) track,split_part(v,'/',3)::int race_no from jsonb_array_elements_text('["2026-10-24/京都/10","2026-10-24/京都/11","2026-10-24/京都/8","2026-10-24/新潟/11","2026-10-24/新潟/7","2026-10-24/東京/8","2026-10-24/東京/9","2026-10-25/京都/11","2026-10-25/京都/7","2026-10-25/京都/8","2026-10-25/新潟/10","2026-10-25/新潟/9","2026-10-25/東京/10","2026-10-25/東京/8","2026-10-31/京都/12","2026-10-31/京都/9","2026-10-31/東京/10","2026-10-31/東京/12","2026-10-31/東京/7","2026-11-01/京都/10","2026-11-01/京都/11","2026-11-01/東京/11","2026-11-01/東京/8","2026-11-01/東京/9","2026-11-07/京都/12","2026-11-07/京都/9","2026-11-07/東京/10","2026-11-07/東京/8","2026-11-07/福島/7","2026-11-08/京都/10","2026-11-08/京都/12","2026-11-14/京都/10","2026-11-14/京都/12","2026-11-14/京都/8","2026-11-14/東京/10","2026-11-14/東京/12","2026-11-14/福島/9","2026-11-15/京都/11","2026-11-15/京都/12","2026-11-15/京都/7","2026-11-15/東京/10","2026-11-15/東京/11","2026-11-15/東京/12","2026-11-15/東京/8","2026-11-15/福島/10","2026-11-15/福島/9"]'::jsonb) v) select coalesce(to_jsonb(p)->>'protocol_version',p.payload#>>'{audit,protocol_version}','UNRECORDED') as recorded_protocol_version,count(*) as predictions from public.official_predictions p join cohort using(race_date,track,race_no) where p.status='FROZEN' group by 1 order by 1;
